const { createHash } = require('crypto');
const request = $input.first().json ?? {};
const update = request.body ?? request;
const headers = request.headers ?? {};
const message = update.message ?? update.edited_message ?? update.callback_query?.message ?? {};
const updateId = String(update.update_id ?? '').trim();
const chatId = String(message.chat?.id ?? '').trim();
if (!/^\d+$/.test(updateId) || !/^-?\d+$/.test(chatId)) throw new Error('TELEGRAM_ENVELOPE_INVALID');
const text = String(update.callback_query?.data ?? message.text ?? message.caption ?? '').trim();
const senderIsBot = Boolean((update.callback_query?.from ?? message.from)?.is_bot);
const eventKind = update.callback_query ? 'CALLBACK' : message.document ? 'DOCUMENT' : Array.isArray(message.photo) && message.photo.length ? 'IMAGE' : text.startsWith('/') ? 'COMMAND' : text ? 'TEXT' : 'OTHER';
const canonical = JSON.stringify(update);
const transportSecret = String(headers['x-director360-transport'] ?? headers['X-Director360-Transport'] ?? '');
return [{ json: {
  channel: 'TELEGRAM', tenant_id: 'rafael-360', owner_id: 'rafael',
  external_update_id: updateId, chat_id: chatId, message_id: String(message.message_id ?? ''),
  sender_is_bot: senderIsBot, event_kind: eventKind, text_content: text,
  payload: update, payload_hash: 'sha256:' + createHash('sha256').update(canonical, 'utf8').digest('hex'),
  transport_secret_hash: createHash('sha256').update(transportSecret, 'utf8').digest('hex')
} }];

const row = $input.first().json ?? {};
return [{ json: {
  accepted: Boolean(row.accepted && row.persisted),
  queued: Boolean(row.queued),
  duplicate: Boolean(row.accepted && row.duplicate && row.persisted),
  update_id: String(row.update_id ?? ''),
  runtime: 'N8N_LOCAL',
  business_state: 'POSTGRES_VISAO360'
} }];
